/**
 * System initialisation for the STM32G4 targets of LDmicro.
 *
 * SystemInit() is called by the code generated by LDmicro (mainPlc()).
 * It selects HSI16 -> PLL -> 80 MHz as system clock: no crystal is needed.
 *
 *   HSI16 / PLLM(2) = 8 MHz, x PLLN(20) = 160 MHz, / PLLR(2) = 80 MHz
 *   HCLK = PCLK1 = PCLK2 = SYSCLK, Flash latency = 3 wait states
 *
 * 80 MHz is reached in the normal mode of voltage range 1: the boost mode
 * and the two steps clock switch needed above 80 MHz are not used.
 *
 * If the PLL cannot be started the MCU keeps running from the HSI16
 * and SystemCoreClock says so: the libraries always compute their dividers
 * from SystemCoreClock.
 *
 * Distributed under the same license as LDmicro (GPL v3 or later).
 */
#include "Lib_mcu.h"

#define LIB_CLOCK_TIMEOUT 200000U

uint32_t SystemCoreClock = 16000000U; /* HSI16 after reset */

const uint8_t AHBPrescTable[16] = {0U, 0U, 0U, 0U, 0U, 0U, 0U, 0U, 1U, 2U, 3U, 4U, 6U, 7U, 8U, 9U};
const uint8_t APBPrescTable[8] = {0U, 0U, 0U, 0U, 1U, 2U, 3U, 4U};

void SystemInit(void)
{
    volatile uint32_t tmp;
    uint32_t          n;

    /* FPU: full access to CP10 and CP11 */
    SCB->CPACR |= ((3UL << (10 * 2)) | (3UL << (11 * 2)));

    /* Cycle counter, used by delay_us() and delay_ms() */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    /* USB Type-C dead battery pull-downs off: PB4 and PB6 are ordinary I/O */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    tmp = RCC->APB1ENR1;
    (void)tmp;
    PWR->CR3 |= PWR_CR3_UCPD_DBDIS;

    if((RCC->CFGR & RCC_CFGR_SWS) == RCC_CFGR_SWS_PLL) {
        SystemCoreClock = 80000000U; /* already done */
        return;
    }

    /* HSI16 on (it is the clock after reset) */
    RCC->CR |= RCC_CR_HSION;
    for(n = 0; ((RCC->CR & RCC_CR_HSIRDY) == 0) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;
    if((RCC->CR & RCC_CR_HSIRDY) == 0)
        return;

    /* 2 wait states are needed up to 90 MHz in voltage range 1 (normal mode); 3 are used as a margin */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_3WS;
    for(n = 0; ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_3WS) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;

    /* PLL: source HSI16, M = 2, N = 20, R = 2, output R enabled */
    RCC->CR &= ~RCC_CR_PLLON;
    for(n = 0; (RCC->CR & RCC_CR_PLLRDY) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI | (1U << RCC_PLLCFGR_PLLM_Pos) | (20U << RCC_PLLCFGR_PLLN_Pos) | (0U << RCC_PLLCFGR_PLLR_Pos) | RCC_PLLCFGR_PLLREN;
    RCC->CR |= RCC_CR_PLLON;
    for(n = 0; ((RCC->CR & RCC_CR_PLLRDY) == 0) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;
    if((RCC->CR & RCC_CR_PLLRDY) == 0) {
        FLASH->ACR &= ~FLASH_ACR_LATENCY;
        return;
    }

    /* HCLK = PCLK1 = PCLK2 = SYSCLK, then switch to the PLL */
    RCC->CFGR &= ~(RCC_CFGR_HPRE | RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2);
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    for(n = 0; ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;
    if((RCC->CFGR & RCC_CFGR_SWS) == RCC_CFGR_SWS_PLL)
        SystemCoreClock = 80000000U;
}

void SystemCoreClockUpdate(void)
{
    if((RCC->CFGR & RCC_CFGR_SWS) == RCC_CFGR_SWS_PLL)
        SystemCoreClock = 80000000U;
    else
        SystemCoreClock = 16000000U;
}
